import { test, expect } from '@playwright/test';

test.describe('Checkout Form Mobile Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });
    // Navigate to checkout page
    await page.goto('/checkout');
    // Wait for form to load
    await page.waitForLoadState('networkidle');
  });

  test('should stack form fields vertically on mobile screen', async ({ page }) => {
    // Get all form field containers
    const formFields = page.locator('[data-testid="form-field"]');
    const fieldCount = await formFields.count();

    // Verify form fields exist
    expect(fieldCount).toBeGreaterThan(0);

    // Check that each field is displayed vertically (full width)
    for (let i = 0; i < fieldCount; i++) {
      const field = formFields.nth(i);
      const boundingBox = await field.boundingBox();

      // Verify field takes up most of the viewport width
      expect(boundingBox?.width).toBeGreaterThan(300);
      expect(boundingBox?.width).toBeLessThanOrEqual(375);
    }

    // Verify fields are stacked (each field below the previous)
    const firstFieldBox = await formFields.nth(0).boundingBox();
    const secondFieldBox = await formFields.nth(1).boundingBox();

    // Second field should be below first field
    expect(secondFieldBox?.top).toBeGreaterThan(firstFieldBox?.top || 0);
  });

  test('should display form labels above input fields on mobile', async ({ page }) => {
    // Get email input and its label
    const emailLabel = page.getByLabel('Email Address');
    const emailInput = page.getByRole('textbox', { name: /email/i });

    // Verify label exists
    await expect(emailLabel).toBeVisible();

    // Get bounding boxes
    const labelBox = await emailLabel.boundingBox();
    const inputBox = await emailInput.boundingBox();

    // Label should be above input (smaller top value)
    expect(labelBox?.top).toBeLessThan(inputBox?.top || 0);

    // Label and input should be aligned horizontally (similar left position)
    expect(Math.abs((labelBox?.left || 0) - (inputBox?.left || 0))).toBeLessThan(10);
  });

  test('should stack submit button full width on mobile', async ({ page }) => {
    // Get submit button
    const submitButton = page.getByRole('button', { name: /complete purchase|submit|checkout/i });

    // Verify button is visible
    await expect(submitButton).toBeVisible();

    // Get button dimensions
    const buttonBox = await submitButton.boundingBox();

    // Button should be full width (accounting for padding)
    expect(buttonBox?.width).toBeGreaterThan(300);
    expect(buttonBox?.width).toBeLessThanOrEqual(375);
  });

  test('should maintain proper spacing between form elements on mobile', async ({ page }) => {
    // Get all form fields
    const formFields = page.locator('[data-testid="form-field"]');
    const fieldCount = await formFields.count();

    // Check spacing between consecutive fields
    for (let i = 0; i < fieldCount - 1; i++) {
      const currentField = formFields.nth(i);
      const nextField = formFields.nth(i + 1);

      const currentBox = await currentField.boundingBox();
      const nextBox = await nextField.boundingBox();

      // Calculate gap between fields
      const gap = (nextBox?.top || 0) - ((currentBox?.top || 0) + (currentBox?.height || 0));

      // Gap should be reasonable (between 8px and 32px)
      expect(gap).toBeGreaterThanOrEqual(8);
      expect(gap).toBeLessThanOrEqual(32);
    }
  });

  test('should display form in single column layout on mobile', async ({ page }) => {
    // Get form container
    const formContainer = page.locator('form, [data-testid="checkout-form"]').first();

    // Verify form is visible
    await expect(formContainer).toBeVisible();

    // Get form dimensions
    const formBox = await formContainer.boundingBox();

    // Form should span viewport width
    expect(formBox?.width).toBeGreaterThan(300);
    expect(formBox?.width).toBeLessThanOrEqual(375);

    // Get all input fields within form
    const inputs = formContainer.locator('input, textarea, select');
    const inputCount = await inputs.count();

    // Verify inputs are stacked vertically
    if (inputCount > 1) {
      const firstInput = inputs.nth(0);
      const lastInput = inputs.nth(inputCount - 1);

      const firstBox = await firstInput.boundingBox();
      const lastBox = await lastInput.boundingBox();

      // Last input should be below first input
      expect((lastBox?.top || 0) - (firstBox?.top || 0)).toBeGreaterThan(0);
    }
  });
});
